import crypto from 'node:crypto';import fs from 'node:fs';import path from 'node:path';import {PDFDocument,StandardFonts} from 'pdf-lib';
export const DUP_WORKSPACE_ID='ws-academy-duplicate-evidence';export const DUP_ENGAGEMENT_ID='eng-academy-duplicate-evidence';export function duplicateEvidenceDir(){return process.env.DUPLICATE_EVIDENCE_ACCEPTANCE_DIR||'/tmp/eve-duplicate-evidence';}export const dupPath=(n:string)=>path.join(duplicateEvidenceDir(),n);export const sha256=(b:Buffer)=>crypto.createHash('sha256').update(b).digest('hex');
export type PdfVariant='base'|'cosmetic'|'material';
export async function buildDuplicatePdf(v:PdfVariant):Promise<Buffer>{const changed=v==='material';const doc=await PDFDocument.create();doc.setTitle('Eve Duplicate Evidence PDF');doc.setAuthor('Eve Academy');doc.setCreator('Eve Academy Fixture Generator');doc.setProducer('Eve Academy Fixture Generator');doc.setCreationDate(new Date('2026-09-16T00:00:00Z'));doc.setModificationDate(new Date('2026-09-16T00:00:00Z'));const p=doc.addPage([612,792]);const f=await doc.embedFont(StandardFonts.Helvetica);const rows=[`ISSUER EVE PDF TEST MARKET`,`RECEIPT R-PDF-2026-0916`,`DATE 09/16/2026`,`SUBTOTAL USD ${changed?'59.10':'49.75'}`,`SALES TAX USD ${changed?'4.13':'3.48'}`,`TOTAL USD ${changed?'63.23':'53.23'}`,`PAYMENT USD ${changed?'63.23':'53.23'}`,`CURRENCY USD`];let y=720;for(const r of rows){p.drawText(r,{x:72,y,size:13,font:f});y-=32;}if(v==='cosmetic')p.drawText('COPY PRESENTATION NOTE - formatting only',{x:72,y:450,size:9,font:f});return Buffer.from(await doc.save({useObjectStreams:false,addDefaultPage:false}));}
export function loadDup(name:string){return fs.readFileSync(dupPath(name));}
